// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 560, H = 300;
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var gSides = draw.group(), gMarks = draw.group(), gHit = draw.group(), gLab = draw.group();

/* ── geometry constants: left vertex anchored, hypotenuse length fixed ── */
var Vx = 140, By = 252, L = 228;

var COL = { a: '#1f6fd0', p: '#e8801a', h: '#1f9d55' };
var ROLE = { a: 'adjacent to θ', p: 'opposite θ', h: 'hypotenuse' };

var theta = 30;
var sel = { a: false, p: false, h: false };
var captionText = '';
var ratioFn = null, ratioSrc = 'p/h', ratioVal = 0.5;

/* ── text helper (serif italic, white halo so labels never sit on strokes) ── */
function mkText(parent, x, y, txt, size, color, anchor, italic) {
  var t = parent.plain(txt);
  t.attr({
    x: x, y: y,
    'text-anchor': anchor || 'middle',
    'dominant-baseline': 'central',
    'font-family': 'Georgia, "Times New Roman", Times, serif',
    'font-size': size,
    'font-style': (italic === false) ? 'normal' : 'italic',
    fill: color || '#000',
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
  return t;
}

function fmt(v) {
  if (!isFinite(v)) return '—';
  return (Math.abs(v) >= 100) ? v.toFixed(1) : v.toFixed(3);
}

function accentKey() {
  var order = ['p', 'a', 'h'];
  for (var i = 0; i < order.length; i++) if (sel[order[i]]) return order[i];
  return null;
}

function tipFor(k) {
  var rad = theta * Math.PI / 180;
  if (k === 'a') return 'a — adjacent to θ   (a = h·cos θ, so cos θ = ' + Math.cos(rad).toFixed(3) + ')';
  if (k === 'p') return 'p — opposite θ   (p = h·sin θ, so sin θ = ' + Math.sin(rad).toFixed(3) + ')';
  return 'h — hypotenuse, always across from the right angle';
}

function drawSide(k, x1, y1, x2, y2) {
  var on = sel[k];
  gSides.line(x1, y1, x2, y2).stroke({ color: on ? COL[k] : '#000', width: on ? 4 : 1.6, linecap: 'round' });
  gHit.line(x1, y1, x2, y2)
    .stroke({ color: '#000', width: 18, opacity: 0 })
    .attr('pointer-events', 'stroke')
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tipFor(k), e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { selectSide(k); });
}

function labelHit(t, k) {
  t.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tipFor(k), e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { selectSide(k); });
}

function render() {
  gSides.clear(); gMarks.clear(); gHit.clear(); gLab.clear();

  var rad = theta * Math.PI / 180;
  var a = L * Math.cos(rad), p = L * Math.sin(rad);
  var Bx = Vx + a, Ay = By - p;

  /* sides */
  drawSide('a', Vx, By, Bx, By);
  drawSide('p', Bx, By, Bx, Ay);
  drawSide('h', Bx, Ay, Vx, By);

  /* right-angle square (open) */
  var s = Math.min(13, 0.3 * a, 0.3 * p);
  gMarks.path('M ' + (Bx - s) + ' ' + By + ' L ' + (Bx - s) + ' ' + (By - s) + ' L ' + Bx + ' ' + (By - s))
    .fill('none').stroke({ color: '#000', width: 1.3 });

  /* arc at acute vertex */
  var acc = accentKey();
  var r = Math.min(36, 0.42 * a, 0.42 * p);
  var bx = Vx + r * Math.cos(rad), by = By - r * Math.sin(rad);
  var arc = gMarks.path('M ' + (Vx + r) + ' ' + By + ' A ' + r + ' ' + r + ' 0 0 0 ' + bx + ' ' + by)
    .fill('none')
    .stroke({ color: acc ? COL[acc] : '#000', width: acc ? 2.4 : 1.2 });
  arc.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('θ = ' + theta.toFixed(0) + '° — the reference angle; every side name is defined relative to it', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The reference angle θ',
        'θ is the acute angle you choose to measure from. The two sides that form θ are the adjacent side and the hypotenuse; the side that does not touch θ is the opposite side. Choose the other acute vertex and the roles of a and p swap.');
    });

  /* labels */
  var la = mkText(gLab, (Vx + Bx) / 2, By + 19, 'a', 19, sel.a ? COL.a : '#000');
  var lp = mkText(gLab, Bx + 13, (By + Ay) / 2, 'p', 19, sel.p ? COL.p : '#000', 'start');
  var mx = (Vx + Bx) / 2, my = (By + Ay) / 2;
  var lh = mkText(gLab, mx - 18 * Math.sin(rad), my - 18 * Math.cos(rad), 'h', 19, sel.h ? COL.h : '#000');
  labelHit(la, 'a'); labelHit(lp, 'p'); labelHit(lh, 'h');

  var rt = r + 17;
  mkText(gLab, Vx + rt * Math.cos(rad / 2), By - rt * Math.sin(rad / 2), 'θ', 16,
    acc ? COL[acc] : '#000');

  /* role caption (only after an interaction) */
  if (captionText) {
    mkText(gLab, 16, 20, captionText, 13, acc ? COL[acc] : '#333', 'start', false);
  }
}

/* ── readouts ───────────────────────────────────────────────────────────── */
function setTxt(id, v) { var e = document.getElementById(id); if (e) e.textContent = v; }

function inverseForm() {
  if (!ratioFn) return null;
  var cands = [
    { label: 'sin⁻¹', color: COL.p, f: function (r) { return Math.sin(r); }, inv: function (v) { return v; }, recip: false },
    { label: 'cos⁻¹', color: COL.a, f: function (r) { return Math.cos(r); }, inv: function (v) { return v; }, recip: false },
    { label: 'tan⁻¹', color: '#7a4fbf', f: function (r) { return Math.tan(r); }, inv: function (v) { return v; }, recip: false },
    { label: 'sin⁻¹', color: COL.p, f: function (r) { return 1 / Math.sin(r); }, inv: function (v) { return 1 / v; }, recip: true },
    { label: 'cos⁻¹', color: COL.a, f: function (r) { return 1 / Math.cos(r); }, inv: function (v) { return 1 / v; }, recip: true },
    { label: 'tan⁻¹', color: '#7a4fbf', f: function (r) { return 1 / Math.tan(r); }, inv: function (v) { return 1 / v; }, recip: true }
  ];
  var tests = [17, 38, 62, 79];
  for (var i = 0; i < cands.length; i++) {
    var ok = true;
    for (var j = 0; j < tests.length; j++) {
      var rr = tests[j] * Math.PI / 180;
      var v = ratioFn(Math.sin(rr), Math.cos(rr), 1);
      if (!isFinite(v) || Math.abs(v - cands[i].f(rr)) > 1e-7) { ok = false; break; }
    }
    if (ok) return cands[i];
  }
  return null;
}

function currentRatio() {
  if (!ratioFn) return NaN;
  var rr = theta * Math.PI / 180;
  var v = ratioFn(Math.sin(rr), Math.cos(rr), 1);
  return isFinite(v) ? v : NaN;
}

function updateReadout() {
  var rad = theta * Math.PI / 180;
  setTxt('roTheta', theta.toFixed(0) + '°');
  setTxt('roPH', Math.sin(rad).toFixed(3));
  setTxt('roAH', Math.cos(rad).toFixed(3));
  setTxt('roPA', Math.tan(rad).toFixed(3));

  var b = document.getElementById('roBanner');
  var v = currentRatio();
  var c = inverseForm();
  if (c && isFinite(v)) {
    var argTxt = c.recip ? ('1/(' + ratioSrc + ')') : ratioSrc;
    b.textContent = 'θ = ' + c.label + '(' + argTxt + ') = ' + c.label + '(' + fmt(c.inv(v)) + ') = ' + theta.toFixed(1) + '°';
    b.style.color = c.color;
  } else if (isFinite(v)) {
    b.textContent = ratioSrc + ' = ' + fmt(v) + '  →  θ = ' + theta.toFixed(1) + '° (solved numerically)';
    b.style.color = '#444';
  } else {
    b.textContent = '';
  }

  var cap = document.getElementById('roleCaptionUI');
  if (cap) { cap.textContent = captionText; cap.style.color = accentKey() ? COL[accentKey()] : '#333'; }
}

function status(msg) {
  var s = document.getElementById('solveStatus');
  if (!s) return;
  if (msg) { s.textContent = msg; s.style.display = ''; } else { s.textContent = ''; s.style.display = 'none'; }
}

/* ── selection ──────────────────────────────────────────────────────────── */
function selectSide(k) {
  sel = { a: false, p: false, h: false };
  sel[k] = true;
  captionText = k + ' — ' + ROLE[k];
  render(); updateReadout();
  var titles = { a: 'a is the adjacent side', p: 'p is the opposite side', h: 'h is the hypotenuse' };
  var bodies = {
    a: 'Side a is one of the two sides that form θ, so relative to θ it is the adjacent side — not "the horizontal side". Measure from the upper acute vertex instead and this same side becomes the opposite side. Since cos θ = a/h, knowing a and h gives θ = cos⁻¹(a/h).',
    p: 'Side p never touches θ; it lies across from it, so it is the opposite side. As θ grows with h fixed, p stretches while a shrinks, which is why the ratio p/a encodes the angle: θ = tan⁻¹(p/a).',
    h: 'The hypotenuse is the one side whose role never depends on θ: it is always the side opposite the right angle, and always the longest. Pair it with p for sine or with a for cosine.'
  };
  showPopup(titles[k], bodies[k]);
}

function clearSel() {
  sel = { a: false, p: false, h: false };
  captionText = '';
  render(); updateReadout();
}

/* ── slider ─────────────────────────────────────────────────────────────── */
function syncValueInputFromTheta() {
  var v = currentRatio();
  var inp = document.getElementById('ratioValueInput');
  if (inp && isFinite(v)) { inp.value = fmt(v); ratioVal = v; }
}

function update_thetaSlider(v) {
  theta = v;
  render();
  syncValueInputFromTheta();
  updateReadout();
  status('');
}

function setTheta(v) {
  theta = v;
  var inp = document.getElementById('thetaSliderInput');
  var out = document.getElementById('thetaSliderVal');
  if (inp) inp.value = v;
  if (out) out.value = v;
  render();
  syncValueInputFromTheta();
  updateReadout();
}

/* ── inverse solve: θ recovered from the compiled ratio function ───────── */
function varsUsed(src) {
  var out = [];
  ['p', 'a', 'h'].forEach(function (k) {
    if (new RegExp('(^|[^A-Za-z0-9_])' + k + '([^A-Za-z0-9_]|$)').test(src)) out.push(k);
  });
  return out;
}

function solveFromInputs() {
  if (!ratioFn) return;
  var target = ratioVal;
  var g = function (d) {
    var rr = d * Math.PI / 180;
    var v = ratioFn(Math.sin(rr), Math.cos(rr), 1);
    return (isFinite(v) ? v : NaN) - target;
  };
  var root = findRoot(g, 0.2, 89.8, 1e-10);
  if (root === null) {
    status('No angle between 0° and 90° makes ' + ratioSrc + ' = ' + fmt(target) + '.');
    updateReadout();
    return;
  }
  status('');
  theta = Math.max(5, Math.min(85, root));
  var inp = document.getElementById('thetaSliderInput');
  var out = document.getElementById('thetaSliderVal');
  if (inp) inp.value = Math.round(theta);
  if (out) out.value = Math.round(theta);

  var used = varsUsed(ratioSrc);
  sel = { a: false, p: false, h: false };
  used.forEach(function (k) { sel[k] = true; });
  var c = inverseForm();
  captionText = used.length ? (used.join(' and ') + ' known' + (c ? '  →  θ = ' + c.label + '(' + ratioSrc + ')' : '')) : '';
  render();
  updateReadout();
}

/* ── equation inputs (scaffold owns parsing) ───────────────────────────── */
render();
updateReadout();

bindEquationInput('ratioExprInput', function (fn, src) {
  ratioFn = fn;
  ratioSrc = src;
  solveFromInputs();
}, { variables: ['p', 'a', 'h'] });

bindEquationInput('ratioValueInput', function (fn) {
  if (fn(0) !== fn(1)) throw new Error('Enter a plain number (e.g. 0.5 or sqrt(2)/2)');
  var v = fn(0);
  if (!isFinite(v)) throw new Error('Value must be a finite number');
  ratioVal = v;
  solveFromInputs();
}, { variables: [] });

/* ── demo steps ─────────────────────────────────────────────────────────── */
var steps = [
  {
    title: 'The reference triangle',
    narration: 'A bare right triangle: base a, vertical side p, hypotenuse h, a square marking the right angle and an arc marking the acute angle θ. There are no numbers — this is a template, not a specific triangle.',
    state: { thetaSlider: 30 }
  },
  {
    title: 'Names are roles, not directions',
    narration: 'Click each label in turn. a lies against θ, so it is adjacent; p sits across from θ, so it is opposite; h stretches between them as the hypotenuse. Move θ to the other vertex in your mind and the names would swap.',
    state: { thetaSlider: 30 }
  },
  {
    title: 'Shallow angle',
    narration: 'θ drops to about 20°. The opposite side p becomes short compared with the adjacent side a, so p/a is small — a small ratio means a small angle.',
    state: { thetaSlider: 20 }
  },
  {
    title: 'Steep angle',
    narration: 'θ rises to about 70°. Now p towers over a and the ratio p/a is large. Every value of θ gives one distinct set of ratios.',
    state: { thetaSlider: 70 }
  },
  {
    title: 'Running it backwards',
    narration: 'A known ratio — p/h = 0.5 — is entered, and the triangle snaps to the angle that produces it, with θ = sin⁻¹(0.5) highlighted. Two measured sides are enough to recover the unknown angle.',
    state: { thetaSlider: 30, ratioExpr: 'p/h', ratioValue: '0.5' }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  setTxt('demoNarration', s.narration);
  setTxt('stepLabel', 'step ' + (stepIdx + 1) + '/' + steps.length + ' · ' + s.title);
  clearSel();
  status('');
  if (s.state && s.state.thetaSlider != null) setTheta(s.state.thetaSlider);
  if (s.state && s.state.ratioExpr != null) {
    var ei = document.getElementById('ratioExprInput');
    var vi = document.getElementById('ratioValueInput');
    ei.value = s.state.ratioExpr;
    vi.value = s.state.ratioValue;
    ei.dispatchEvent(new Event('input'));
    vi.dispatchEvent(new Event('input'));
  }
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In a right triangle, the names adjacent, opposite, and hypotenuse are roles defined relative to a chosen acute angle θ, and any two of those side lengths determine θ through an inverse trigonometric relation.
KEY INSIGHT (what students should walk away understanding): Adjacent, opposite, and hypotenuse are roles assigned by θ, not fixed directions on the page — and because each angle produces its own unique set of side ratios, reading a ratio backwards through an inverse trig function recovers the angle.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
